import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../application/watchlist_providers.dart';
class NotificationPreferencesScreen extends ConsumerWidget{const NotificationPreferencesScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final p=ref.watch(alertPreferenceProvider);void save(dynamic Function() value)=>ref.read(alertPreferenceProvider.notifier).set(value());return Scaffold(appBar:AppBar(title:const Text('Notification preferences')),body:ListView(children:[_s('Price drop alerts',p.priceDrops,(v)=>save(()=>p.copyWith(priceDrops:v))),_s('Product availability alerts',p.availability,(v)=>save(()=>p.copyWith(availability:v))),_s('Offer alerts',p.offers,(v)=>save(()=>p.copyWith(offers:v))),_s('Nearby seller alerts',p.nearbySellers,(v)=>save(()=>p.copyWith(nearbySellers:v))),_s('Requested product alerts',p.requestedProducts,(v)=>save(()=>p.copyWith(requestedProducts:v))),const Divider(),_s('Instant alerts',p.instant,(v)=>save(()=>p.copyWith(instant:v))),_s('Daily summary',p.daily,(v)=>save(()=>p.copyWith(daily:v))),_s('Weekly summary',p.weekly,(v)=>save(()=>p.copyWith(weekly:v))),_s('Quiet hours (10 PM–7 AM)',p.quietHours,(v)=>save(()=>p.copyWith(quietHours:v)))]));}Widget _s(String title,bool value,ValueChanged<bool> changed)=>SwitchListTile(title:Text(title),value:value,onChanged:changed);}
